import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {spawnSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
const appRoot='/Users/luca/Desktop/项目/muse';
const gstackRoot='/Users/luca/Desktop/luca_gstack';
const from=(root,rel)=>import(pathToFileURL(`${root}/${rel}`).href);
const {getProvider}=await from(appRoot,'app/cli-providers.js');
const {encodeSessionKey,decodeSessionKey,resolveDraftSource}=await from(appRoot,'app/session-source.js');
const {createSettingsStore,createEmptySettings}=await from(appRoot,'app/settings-store.js');
const {validateSessionResumeAtSource,inspectProviderLive}=await from(appRoot,'app/session-runtime.js');
const {actualHarness,capabilities}=await from(gstackRoot,'.claude/hooks/lib/harness.mjs');
const {resolve}=await from(gstackRoot,'scripts/model-route.mjs');
const policyProcess=spawnSync('python3',['-c','import json,yaml,sys; print(json.dumps(yaml.safe_load(open(sys.argv[1]))["model_routing"]))',`${gstackRoot}/.claude/skill-os/model-routing.yaml`],{encoding:'utf8'});
assert.equal(policyProcess.status,0);
const policy=JSON.parse(policyProcess.stdout);
let state=createEmptySettings(),ioCalls=0;
const settings=createSettingsStore({
  writer:{read:async()=>{ioCalls++;return structuredClone(state);},transaction:async(spec,mutate)=>{ioCalls++;const next=structuredClone(state);mutate(next);state=next;return {state:structuredClone(state)};}},
  credentialBackend:{status:async()=>{throw Error('unexpected credential access');},set:async()=>{throw Error('unexpected credential access');},remove:async()=>{throw Error('unexpected credential access');}}
});
const observed=[];
for(const provider of ['claude','codex']){
  assert.equal(getProvider(provider).id,provider);
  const key=encodeSessionKey({provider,sourceId:'src_fixture_0001',nativeSessionId:'fixture-session'});
  assert.equal(decodeSessionKey(key).provider,provider);
  observed.push({probe:'known-provider-control',provider,result:'correct provider and round-trip session key'});
}
for(const provider of ['muse','grok','misspelled-cli']){
  const mapped=getProvider(provider).id;
  assert.equal(mapped,'claude');
  observed.push({probe:'unknown-provider-lookup',provider,mapped});
  let error=null;
  try{encodeSessionKey({provider,sourceId:'src_fixture_0001',nativeSessionId:'fixture-session'});}catch(e){error=e.code;}
  assert.equal(error,'invalid_provider');
  observed.push({probe:'unknown-session-provider',provider,error});
  assert.equal(resolveDraftSource([],{provider,profileId:`${provider}:native`,canonicalRealpath:gstackRoot}),null);
  observed.push({probe:'unknown-draft-source',provider,result:null});
}
const beforeIo=ioCalls;
let settingsError=null;
try{await settings.preferencesPatch({patch:{defaultProvider:'muse'},basePreferenceRevision:0,operationId:'probe-muse'});}catch(e){settingsError=e.code;}
assert.equal(settingsError,'invalid_preferences_patch');
assert.equal(ioCalls,beforeIo);
observed.push({probe:'muse-preference-write',error:settingsError,storage_or_credential_access:false});
const accepted=await settings.preferencesPatch({patch:{defaultProvider:'codex'},basePreferenceRevision:0,operationId:'probe-known'});
assert.equal(accepted.preferences.defaultProvider,'codex');
observed.push({probe:'known-preference-control',result:accepted.preferences.defaultProvider,storage:'in-memory-only'});
const resumed=await validateSessionResumeAtSource({home:'/nonexistent-fixture',cwd:gstackRoot,provider:'muse',sid:'fixture',sourceRoot:'/nonexistent-fixture'});
assert.equal(resumed.ok,false);
assert.equal(resumed.reason,'Unsupported session provider.');
observed.push({probe:'muse-resume',result:resumed});
await assert.rejects(inspectProviderLive('/nonexistent-fixture','muse',new Map()),/invalid provider/);
observed.push({probe:'muse-process-inspection',result:'rejected before process scan'});
for(const harness of ['muse-native','grok-native']){
  const route=resolve({harness,scene:'MR-001',role_config:policy});
  assert.deepEqual(route,{disposition:'REFUSE',reason:'UNSUPPORTED_HARNESS'});
  observed.push({probe:'third-harness-model-route',harness,result:route});
}
for(const provider of ['muse','grok']){
  const actual=actualHarness({LUCA_ACTUAL_HARNESS:provider});
  assert.equal(actual,'unknown');
  const caps=capabilities(actual);
  assert.equal(caps.contextInjection,true);
  assert.equal(caps.inputMutation,true);
  observed.push({probe:'third-harness-identity-and-static-capabilities',provider,actual,caps});
}
const evidence={scope:'isolated current public-function contracts, no real CLI/model/config changes',count:observed.length,observed};
writeFileSync(new URL('./contract-probes.json',import.meta.url),JSON.stringify(evidence,null,2));
console.log(JSON.stringify(evidence,null,2));
